        return try writer.write(Serializable{ .@"type" = std.meta.activeTag(self.data), .object = "stmt", .value = self.data, .loc = self.loc });
}

pub fn isTypeScript(self: *Stmt) bool {
        return (@as(Tag, @enumFromInt(self.data)) == .s_type_script);
}

pub fn isSuperCall(self: Stmt) bool {
        return (((self.data == .s_expr) and ((if (@typeInfo(@TypeOf(self.data.s_expr)) == .@"enum") @intFromEnum(self.data.s_expr) else self.data.s_expr.value).data == .e_call)) and ((if (@typeInfo(@TypeOf(self.data.s_expr)) == .@"enum") @intFromEnum(self.data.s_expr) else self.data.s_expr.value).data.e_call.target.data == .e_super));
}

pub fn isMissingExpr(self: Stmt) bool {
        return ((self.data == .s_expr) and ((if (@typeInfo(@TypeOf(self.data.s_expr)) == .@"enum") @intFromEnum(self.data.s_expr) else self.data.s_expr.value).data == .e_missing));
}

pub fn empty() Stmt {
        return Stmt{ .data = .{ .s_empty = None }, .loc = logger.Loc{  } };
}

pub fn toEmpty(self: Stmt) Stmt {
        return Stmt{ .data = .{ .s_empty = None }, .loc = self.loc };
}

pub fn caresAboutScope(self: *Stmt) bool {
        return (switch (self.data) {
.s_block, .s_empty, .s_debugger, .s_expr, .s_if, .s_for, .s_for_in, .s_for_of, .s_do_while, .s_while, .s_with, .s_try, .s_switch, .s_return, .s_throw, .s_break, .s_continue, .s_directive => {
return false;
},
.s_local => |local| {
return (local.kind != .k_var);
},
else => {
return true;
},
});
}

pub fn assign(a: Expr, b: Expr) Stmt {
        return Stmt.alloc(S.SExpr, S.SExpr{ .value = Expr.assign(a, b) }, a.loc);
}

