pe) == S.For) Stmt.comptime_init("s_for", S.For, origData, loc) else if ((comptime StatementType) == S.Function) Stmt.comptime_init("s_function", S.Function, origData, loc) else if ((comptime StatementType) == S.If) Stmt.comptime_init("s_if", S.If, origData, loc) else if ((comptime StatementType) == S.Import) Stmt.comptime_init("s_import", S.Import, origData, loc) else if ((comptime StatementType) == S.Label) Stmt.comptime_init("s_label", S.Label, origData, loc) else if ((comptime StatementType) == S.Local) Stmt.comptime_init("s_local", S.Local, origData, loc) else if ((comptime StatementType) == S.Namespace) Stmt.comptime_init("s_namespace", S.Namespace, origData, loc) else if ((comptime StatementType) == S.Return) Stmt.comptime_init("s_return", S.Return, origData, loc) else if ((comptime StatementType) == S.Switch) Stmt.comptime_init("s_switch", S.Switch, origData, loc) else if ((comptime StatementType) == S.Throw) Stmt.comptime_init("s_throw", S.Throw, origData, loc) else if ((comptime StatementType) == S.Try) Stmt.comptime_init("s_try", S.Try, origData, loc) else if ((comptime StatementType) == S.TypeScript) Stmt.comptime_init("s_type_script", S.TypeScript, origData, loc) else if ((comptime StatementType) == S.While) Stmt.comptime_init("s_while", S.While, origData, loc) else if ((comptime StatementType) == S.With) Stmt.comptime_init("s_with", S.With, origData, loc) else @compileError("Invalid type in Stmt.init"));
