pub inline fn comptime_alloc(comptime tag_name: []const u8, comptime typename: type, origData: anytype, loc: logger.Loc) Stmt {
        return Stmt{ .loc = loc, .data = @unionInit(Data, tag_name, Data.Store.append(typename, origData)) };
}

pub fn allocateData(allocator: std.mem.Allocator, comptime tag_name: []const u8, comptime typename: type, origData: anytype, loc: logger.Loc) Stmt {
    _ = typename;
        const value = ((allocator.create(@TypeOf(origData))) catch unreachable);
        {
            value.* = origData;
        }
        return comptime_init(tag_name, @TypeOf(value), value, loc);
}

pub inline fn comptime_init(comptime tag_name: []const u8, comptime TypeName: type, origData: TypeName, loc: logger.Loc) Stmt {
        return Stmt{ .loc = loc, .data = @unionInit(Data, tag_name, origData) };
}

pub fn alloc(comptime StatementData: type, origData: StatementData, loc: logger.Loc) Stmt {
        if ((@typeInfo(StatementData) == .@"type")) {
            return Stmt.alloc(origData, std.mem.zeroes(origData), loc);
        }
        _ = Stmt.Data.Store.assert();
        icount = (icount + 1);
        return (if (StatementData == S.Block) Stmt.comptime_alloc("s_block", S.Block, origData, loc) else if (StatementData == S.Break) Stmt.comptime_alloc("s_break", S.Break, origData, loc) else if (StatementData == S.Class) Stmt.comptime_alloc("s_class", S.Class, origData, loc) else if (StatementData == S.Comment) Stmt.comptime_alloc("s_comment", S.Comment, origData, loc) else if (StatementData == S.Continue) Stmt.comptime_alloc("s_continue", S.Continue, origData, loc) else if (StatementData == S.Debugger) Stmt{ .loc = loc, .data = .{ .s_debugger = origData } } else if (StatementData == S.Directive) Stmt.comptime_alloc("s_directive", S.Directive, origData, loc) else if (StatementData == S.DoWhile) Stmt.comptime_alloc("s_do_while", S.DoWhile, origData, loc) else if (StatementData == S.Empty) Stmt{ .loc = loc, .data = Data{ .s_empty = std.mem.zeroes(S.Empty) } } else if (StatementData == S.Enum) Stmt.comptime_alloc("s_enum", S.Enum, origData, loc) else if (StatementData == S.ExportClause) Stmt.comptime_alloc("s_export_clause", S.ExportClause, origData, loc) else if (StatementData == S.ExportDefault) Stmt.comptime_alloc("s_export_default", S.ExportDefault, origData, loc) else if (StatementData == S.ExportEquals) Stmt.comptime_alloc("s_export_equals", S.ExportEquals, origData, loc) else if (StatementData == S.ExportFrom) Stmt.comptime_alloc("s_export_from", S.ExportFrom, origData, loc) else if (StatementData == S.ExportStar) Stmt.comptime_alloc("s_export_star", S.ExportStar, origData, loc) else if (StatementData == S.SExpr) Stmt.comptime_alloc("s_expr", S.SExpr, origData, loc) else if (StatementData == S.ForIn) Stmt.comptime_alloc("s_for_in", S.ForIn, origData, loc) else if (StatementData == S.ForOf) Stmt.comptime_alloc("s_for_of", S.ForOf, origData, loc) else if (StatementData == S.For) Stmt.comptime_alloc("s_for", S.For, origData, loc) else if (StatementData == S.Function) Stmt.comptime_alloc("s_function", S.Function, origData, loc) else if (StatementData == S.If) Stmt.comptime_alloc("s_if", S.If, origData, loc) else if (StatementData == S.Import) Stmt.comptime_alloc("s_import", S.Import, origData, loc) else if (StatementData == S.Label) Stmt.comptime_alloc("s_label", S.Label, origData, loc) else if (StatementData == S.Local) Stmt.comptime_alloc("s_local", S.Local, origData, loc) else if (StatementData == S.Namespace) Stmt.comptime_alloc("s_namespace", S.Namespace, origData, loc) else if (StatementData == S.Return) Stmt.comptime_alloc("s_return", S.Return, origData, loc) else if (StatementData == S.Switch) Stmt.comptime_alloc("s_switch", S.Switch, origData, loc) else if (StatementData == S.Throw) Stmt.comptime_alloc("s_throw", S.Throw, origData, loc) else if (StatementData == S.Try) Stmt.comptime_alloc("s_try", S.Try, origData, loc) else if (StatementData == S.TypeScript) Stmt{ .loc = loc, .data = Data{ .s_type_script = std.mem.zeroes(S.TypeScript) } } else if (StatementData == S.While) Stmt.comptime_alloc("s_while", S.While, origData, loc) else if (StatementData == S.With) Stmt.comptime_alloc("s_with", S.With, origData, loc) else @compileError("Invalid type in Stmt.init"));
}

